<script setup lang="ts">import {computed} from 'vue';import type {Pair} from '../types/domain';import {num,pvalue} from '../utils/format';const props=defineProps<{pairs:Pair[];alpha:number}>();const hasWinner=computed(()=>props.pairs.some(p=>p.win_fraction!=null));function direction(p:Pair){if(p.win_ci_lower==null||p.win_ci_upper==null)return '—';if(p.win_ci_lower>0.5)return `左胜 · ${p.left_code}`;if(p.win_ci_upper<0.5)return `右胜 · ${p.right_code}`;return '跨0.5 · 方向未定';}function methodLabel(m?:string){if(!m)return '—';if(m.includes('max-deviation'))return '整族max偏差';if(m.includes('degenerate'))return '退化点估计';return m;}</script><template><div class="table-scroll"><table class="pair-table"><thead><tr><th>全部预定义组对</th><th>秩均值差<br/>左−右</th><th>SE / z</th><th>双侧原始p<br/>渐近正态</th><th>Holm p</th><th>α={{alpha}}</th><template v-if="hasWinner"><th>左优胜比例<br/>并列计半</th><th>族控区间<br/>1−α同时覆盖</th><th>方向 / 区间法</th></template></tr></thead><tbody><tr v-for="p in pairs" :key="p.left_code+p.right_code"><td><b>{{p.left_code}} {{p.left_name}}</b><small>对 {{p.right_code}} {{p.right_name}}</small></td><td>{{num(p.mean_rank_difference,4)}}</td><td>{{num(p.standard_error,4)}}<small>z {{num(p.z,4)}}</small></td><td>{{pvalue(p.p_raw_asymptotic)}}</td><td>{{pvalue(p.p_holm)}}</td><td :class="p.reject?'reject':'muted'">{{p.reject?'拒绝该组对零假设':'未拒绝'}}</td><template v-if="hasWinner"><td v-if="p.win_fraction!=null">{{num(p.win_fraction,4)}}<small>SE {{num(p.win_bootstrap_se,4)}}</small></td><td v-else class="muted">旧数据未计算</td><td v-if="p.win_ci_lower!=null" :class="p.win_ci_covers_half?'muted':'reject'">[{{num(p.win_ci_lower,3)}}, {{num(p.win_ci_upper,3)}}]</td><td v-else class="muted">—</td><td v-if="p.win_fraction!=null" :class="p.win_ci_covers_half?'muted':'reject'">{{direction(p)}}<small>{{methodLabel(p.win_interval_method)}}</small></td><td v-else class="muted">—</td></template></tr></tbody></table></div></template>
